DROP VIEW "invoice_with_sum";--> statement-breakpoint
DROP VIEW "items_with_tax";--> statement-breakpoint
ALTER TABLE "invoice_item" RENAME TO "line_item";--> statement-breakpoint
ALTER TABLE "line_item" DROP COLUMN "net_amount";--> statement-breakpoint
ALTER TABLE "line_item" ADD COLUMN "net_amount" numeric(19,4) GENERATED ALWAYS AS ("line_item"."quantity" * "line_item"."unit_cost") STORED;--> statement-breakpoint
CREATE VIEW "items_with_tax" WITH (security_invoker = true) AS (select "line_item"."id", "line_item"."invoice_id", "line_item"."label", "line_item"."note", "line_item"."quantity", "line_item"."unit", "line_item"."unit_cost", "line_item"."net_amount", "line_item"."order", "line_item"."user_id", "line_item"."config_id", "config"."tax_registration", ((1 + COALESCE(sum("tax"."rate") * "config"."tax_registration"::INT, 0)) * "line_item"."net_amount")::NUMERIC(19, 4) as "gross_amount" from "line_item" left join "item_tax" on "item_tax"."item_id" = "line_item"."id" left join "tax" on "item_tax"."tax_id" = "tax"."id" left join "invoice" on "line_item"."invoice_id" = "invoice"."id" left join "config" on "invoice"."config_id" = "config"."id" group by "line_item"."id", "config"."id");--> statement-breakpoint
CREATE VIEW "invoice_with_sum" WITH (security_barrier = true, security_invoker = true) AS (select "invoice"."id", "invoice"."user_id", "invoice"."client_data_id", "invoice"."title", "invoice"."description", "invoice"."created_at", "invoice"."issued_at", "invoice"."issue_year", "invoice"."due_at", "invoice"."index", "invoice"."year_index", "invoice"."config_id", "config"."tax_registration", "config"."currency", coalesce(sum("items_with_tax"."net_amount"),0) as "net_total", coalesce(sum("items_with_tax"."gross_amount"),0) as "gross_total" from "invoice" inner join "config" on "invoice"."config_id" = "config"."id" left join "items_with_tax" on "items_with_tax"."invoice_id" = "invoice"."id" group by "invoice"."id", "config"."id");--> statement-breakpoint
ALTER POLICY "granular-crud-authenticated-policy-select" ON "line_item" TO "authenticated" USING ((select current_setting('app.user_id')::uuid = "line_item"."user_id"));--> statement-breakpoint
ALTER POLICY "granular-crud-authenticated-policy-insert" ON "line_item" TO "authenticated" WITH CHECK ((select current_setting('app.user_id')::uuid = "line_item"."user_id"));